# A guardian may be linked only to a student of the same school. The school of
# a student is its class's school, which a CHECK cannot reach, so a trigger
# guards every insert and every change of either side of a link.
SAME_SCHOOL_SQL = """
CREATE FUNCTION main_studentguardian_same_school() RETURNS trigger AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM main_student s
        JOIN main_classinfo c ON c.id = s.class_info_id
        JOIN main_guardian g ON g.id = NEW.guardian_id
        WHERE s.id = NEW.student_id AND c.school_id = g.school_id
    ) THEN
        RAISE EXCEPTION 'guardian % and student % are not in the same school',
            NEW.guardian_id, NEW.student_id USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER main_studentguardian_same_school
BEFORE INSERT OR UPDATE OF student_id, guardian_id ON main_studentguardian
FOR EACH ROW EXECUTE FUNCTION main_studentguardian_same_school();
"""

SAME_SCHOOL_REVERSE_SQL = """
DROP TRIGGER IF EXISTS main_studentguardian_same_school ON main_studentguardian;
DROP FUNCTION IF EXISTS main_studentguardian_same_school();
"""


